import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { createPortal } from 'react-dom';
import type { BankStatementImportRow, BatchDetailLine } from '../../../../../services/kt/bankStatementImportModels';
import { extractBulkRefsFromDescription, normalizeBulkRef } from '../../../../../utils/extractBatchRefs';
import { isBatchLineSuccess, sumBatchLineAmounts } from '../../../../../utils/batchPaymentStatus';
import {
  findStatementRowForLink,
  gdDisplayAmount,
  gdMoneyColor,
  gdSignedAmountForBatchMatch,
  isBatchHubCandidate,
  isDefaultPickerTxCandidate,
  isHoanTienStatementRow,
  pickBatchGroupMainIndex,
} from '../../../../../utils/batchStatementLinkEligibility';
import { getExpenseImportFilterCodes } from '../../../../../services/kt/bankStatementPostingRules';
import styles from './Step1Upload.module.css';

/** Map lô ↔ mã GD sao kê — đẩy lên StepCreateImp → POST Links. */
export type ReconcileStatementBatchLink = {
  statementRowIndex: number;
  statementImportReference?: string;
  statementReferenceCode?: string;
  batchRef: string;
};

function formatAmount(n?: number): string {
  if (n == null) return '—';
  return n.toLocaleString('vi-VN');
}

/** Tiền GD hiển thị (tuyệt đối). */
function gdAmount(row: BankStatementImportRow): number {
  return gdDisplayAmount(row);
}

function PortalOverlay(props: { onClose: () => void; children: React.ReactNode }): React.ReactElement {
  return createPortal(
    <div className={styles.explainOverlay} onClick={props.onClose} role="presentation">
      {props.children}
    </div>,
    document.body,
  );
}

/** Chuẩn hoá ngày DD/MM/YYYY | D/M/YYYY | có giờ | ISO → key so khớp. */
function normDateKey(d?: string): string {
  if (!d) return '';
  const s = d.trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) {
    return `${iso[3].padStart(2, '0')}/${iso[2].padStart(2, '0')}/${iso[1]}`;
  }
  const m = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return s;
  const dd = m[1].padStart(2, '0');
  const mm = m[2].padStart(2, '0');
  let yyyy = m[3];
  if (yyyy.length === 2) yyyy = `20${yyyy}`;
  return `${dd}/${mm}/${yyyy}`;
}

interface BatchReconcileProps {
  saoke: BankStatementImportRow[];
  batches: { file: File; lines: BatchDetailLine[] }[];
  /** Seed map lô↔GD từ DB (Review map Step 3). */
  initialLinks?: ReconcileStatementBatchLink[];
  /** Mỗi lần gán/đổi lô — emit map đầy đủ (main + GD phụ × từng lô). */
  onReconcileLinksChange?: (links: ReconcileStatementBatchLink[]) => void;
}

type BRecGroup = {
  batchRef: string;
  sheetDate?: string;
  fileName: string;
  /** Relative path file (không lineno) hoặc path:tab:… từ dòng đầu. */
  sourcePath?: string;
  lineCount: number;
  /** Gross = Thành công + Thất bại. */
  totalAmount: number;
  /** Tổng Thành công — dùng khi so khớp tiền với sao kê. */
  successAmount: number;
  /** Tổng Thất bại — không tham gia khớp tiền. */
  failedAmount: number;
  successCount: number;
  failedCount: number;
  lines: BatchDetailLine[];
};

/** Path hiển thị trên grid — ưu tiên sourcePath dòng; fallback tên file. */
function batchGroupPath(g: { sourcePath?: string; fileName?: string; lines?: BatchDetailLine[] }): string {
  const fromLine = g.lines?.find(l => l.sourcePath)?.sourcePath;
  return fromLine || g.sourcePath || g.fileName || '—';
}

/** Số tiền dùng để so khớp với GD sao kê = chỉ Thành công. */
function batchMatchAmount(g: { successAmount: number }): number {
  return g.successAmount;
}

/** File key từ importReference (`path:lineno`) — so khớp GD cùng file sao kê. */
function sourceFileKey(importReference?: string): string {
  if (!importReference) return '';
  const m = importReference.trim().match(/^(.*):(\d+)$/);
  return (m ? m[1] : importReference).replace(/\\/g, '/').toLowerCase();
}

function gdRefLabel(row: BankStatementImportRow): string {
  return row.referenceCode?.trim()
    || extractBulkRefsFromDescription(row.description)[0]
    || `#${row.rowIndex}`;
}

/**
 * Đối soát: danh sách GD sao kê có thông tin lô.
 * Click GD → slide-out chọn/đổi/gán nhiều lô (1 GD ↔ nhiều lô).
 * Filter/sort lô theo ngày — default = ngày giao dịch của GD.
 */
const BatchReconcilePanel: React.FC<BatchReconcileProps> = ({
  saoke,
  batches,
  initialLinks,
  onReconcileLinksChange,
}) => {
  const [manualMap, setManualMap] = useState<Record<string, number>>({});
  const [suppressedAuto, setSuppressedAuto] = useState<Record<string, true>>({});
  /** Main rowIndex → extra sao kê rowIndexes gắn cùng lô. */
  const [extraGdByMain, setExtraGdByMain] = useState<Record<number, number[]>>({});
  const [linksSeeded, setLinksSeeded] = useState(false);
  /** GD đang mở slide-out gán lô (giữ object — tránh find theo rowIndex trùng). */
  const [assignGd, setAssignGd] = useState<BankStatementImportRow | null>(null);
  /** Lô đang tick trong slide-out. */
  const [selectedBatchRefs, setSelectedBatchRefs] = useState<string[]>([]);
  /** GD sao kê phụ (cùng file) đang tick — ngoài sao kê chính. */
  const [selectedExtraIdxs, setSelectedExtraIdxs] = useState<number[]>([]);
  const [pickerTab, setPickerTab] = useState<'lo' | 'gd'>('lo');
  const [batchSearch, setBatchSearch] = useState('');
  /** Filter ngày lô trong slide-out — default = ngày GD. */
  const [batchDateFilter, setBatchDateFilter] = useState<string>('');
  /** Filter tab Giao dịch. */
  const [txDateFilter, setTxDateFilter] = useState<string>('');
  const [txSearch, setTxSearch] = useState('');
  const [listDateFilter, setListDateFilter] = useState<string>('');
  const [filterMode, setFilterMode] = useState<'all' | 'mapped' | 'mismatched' | 'unmapped'>('all');
  /** Hiện mọi GD sao kê (bỏ lọc hub / ref / hoàn tiền) — user tự gắn GD hoàn để khớp số. */
  const [showAllGiaoDich, setShowAllGiaoDich] = useState(false);
  const [detailLine, setDetailLine] = useState<{ batchRef: string; idx: number } | null>(null);

  /** Seed từ DB links (một lần) — resolve theo importReference; Chi ưu tiên làm main; Thu+Chi cùng nhóm. */
  useEffect(() => {
    if (linksSeeded || !initialLinks?.length) return;
    const byBatch = new Map<string, number[]>();
    for (const l of initialLinks) {
      if (!l.batchRef) continue;
      const row = findStatementRowForLink(saoke, l);
      if (!row) continue;
      const arr = byBatch.get(l.batchRef) ?? [];
      arr.push(row.rowIndex);
      byBatch.set(l.batchRef, arr);
    }
    const manual: Record<string, number> = {};
    const extras: Record<number, number[]> = {};
    for (const [ref, idxs] of byBatch) {
      const uniq = [...new Set(idxs)];
      const main = pickBatchGroupMainIndex(uniq, idx => saoke.find(r => r.rowIndex === idx));
      if (main < 0) continue;
      manual[ref] = main;
      const rest = uniq.filter(i => i !== main);
      if (rest.length) {
        const merged = new Set([...(extras[main] ?? []), ...rest]);
        extras[main] = [...merged];
      }
    }
    setManualMap(manual);
    setExtraGdByMain(extras);
    setLinksSeeded(true);
  }, [initialLinks, linksSeeded, saoke]);

  const bgroups = useMemo((): BRecGroup[] => {
    const map = new Map<string, BRecGroup>();
    for (const d of batches) {
      const rel = (d.file as File & { webkitRelativePath?: string }).webkitRelativePath?.trim();
      const filePath = (rel && rel.includes('/')) ? rel.replace(/\\/g, '/') : d.file.name;
      for (const l of d.lines) {
        if (!l.batchRef) continue;
        const key = l.batchRef;
        if (!map.has(key)) {
          map.set(key, {
            batchRef: key,
            sheetDate: l.sheetDate,
            fileName: d.file.name,
            sourcePath: l.sourcePath || filePath,
            lineCount: 0,
            totalAmount: 0,
            successAmount: 0,
            failedAmount: 0,
            successCount: 0,
            failedCount: 0,
            lines: [],
          });
        }
        const g = map.get(key)!;
        g.lineCount += 1;
        g.lines.push(l);
        if (!g.sheetDate && l.sheetDate) g.sheetDate = l.sheetDate;
        if (!g.sourcePath && l.sourcePath) g.sourcePath = l.sourcePath;
      }
    }
    for (const g of map.values()) {
      const br = sumBatchLineAmounts(g.lines);
      g.totalAmount = br.totalAmount;
      g.successAmount = br.successAmount;
      g.failedAmount = br.failedAmount;
      g.successCount = br.successCount;
      g.failedCount = br.failedCount;
    }
    return [...map.values()].sort((a, b) =>
      (a.sheetDate ?? '').localeCompare(b.sheetDate ?? '') || a.batchRef.localeCompare(b.batchRef),
    );
  }, [batches]);

  const bgroupByRef = useMemo(() => {
    const m = new Map<string, BRecGroup>();
    for (const g of bgroups) m.set(g.batchRef, g);
    return m;
  }, [bgroups]);

  const autoMap = useMemo(() => {
    const m = new Map<string, BankStatementImportRow>();
    for (const row of saoke) {
      if ((row.debitAmount ?? 0) <= 0) continue;
      const refs = extractBulkRefsFromDescription(row.description);
      for (const ref of refs) {
        const norm = normalizeBulkRef(ref);
        for (const g of bgroups) {
          if (normalizeBulkRef(g.batchRef) === norm || g.batchRef === ref) {
            if (!m.has(g.batchRef)) m.set(g.batchRef, row);
          }
        }
      }
    }
    return m;
  }, [saoke, bgroups]);

  const resolveMappedRow = useCallback((batchRef: string): BankStatementImportRow | undefined => {
    const manualIdx = manualMap[batchRef];
    if (manualIdx !== undefined) return saoke.find(r => r.rowIndex === manualIdx);
    if (suppressedAuto[batchRef]) return undefined;
    return autoMap.get(batchRef);
  }, [manualMap, suppressedAuto, saoke, autoMap]);

  /** Main của nhóm (main + GD phụ gắn cùng lô). */
  const resolveGroupMainIdx = useCallback((rowIndex: number): number => {
    if (extraGdByMain[rowIndex]) return rowIndex;
    for (const [main, extras] of Object.entries(extraGdByMain)) {
      if (extras.includes(rowIndex)) return Number(main);
    }
    return rowIndex;
  }, [extraGdByMain]);

  const batchesForRow = useCallback((rowIndex: number): BRecGroup[] => {
    const mainIdx = resolveGroupMainIdx(rowIndex);
    const refs = new Set<string>();
    for (const [ref, idx] of Object.entries(manualMap)) {
      if (idx === mainIdx) refs.add(ref);
    }
    for (const [ref, row] of autoMap) {
      if (row.rowIndex === mainIdx && manualMap[ref] === undefined && !suppressedAuto[ref]) {
        refs.add(ref);
      }
    }
    return [...refs].map(r => bgroupByRef.get(r)).filter((g): g is BRecGroup => !!g);
  }, [manualMap, autoMap, suppressedAuto, bgroupByRef, resolveGroupMainIdx]);

  const linkedBatchTotal = useCallback((rowIndex: number): number => {
    return batchesForRow(rowIndex).reduce((s, g) => s + batchMatchAmount(g), 0);
  }, [batchesForRow]);

  /** Sum sao kê nhóm: Chi cộng · Thu (hoàn tiền) trừ → khớp tổng Thành công lô. */
  const groupSaokeSum = useCallback((mainIdx: number): number => {
    const members = [mainIdx, ...(extraGdByMain[mainIdx] ?? [])];
    return members.reduce((s, i) => {
      const r = saoke.find(x => x.rowIndex === i);
      return s + (r ? gdSignedAmountForBatchMatch(r) : 0);
    }, 0);
  }, [extraGdByMain, saoke]);

  const rowGroupMatch = useCallback((rowIndex: number) => {
    const mainIdx = resolveGroupMainIdx(rowIndex);
    const linked = batchesForRow(rowIndex);
    // Chỉ sum Thành công — bỏ qua Thất bại khi so khớp tiền
    const batchSum = linked.reduce((s, g) => s + batchMatchAmount(g), 0);
    const saokeSum = groupSaokeSum(mainIdx);
    const variance = saokeSum - batchSum;
    const matched = linked.length > 0 && Math.abs(variance) <= 1;
    return {
      mainIdx,
      isExtra: mainIdx !== rowIndex,
      memberCount: 1 + (extraGdByMain[mainIdx]?.length ?? 0),
      linked,
      batchSum,
      saokeSum,
      variance,
      matched,
    };
  }, [resolveGroupMainIdx, batchesForRow, groupSaokeSum, extraGdByMain]);

  /**
   * Danh sách đối soát — hub chưa có ĐT (mặc định Chi; «Hiện tất cả» = Chi+Thu hub).
   * Ẩn dòng phụ (đã gắn dưới main) — tránh trùng / thiếu nhóm sau seed links.
   * GD đã có ĐT chỉ chọn ở tab Giao dịch khi gán lô.
   */
  const gdRows = useMemo(() => {
    const extraIdxSet = new Set<number>();
    for (const extras of Object.values(extraGdByMain)) {
      for (const i of extras) extraIdxSet.add(i);
    }
    const skipCodes = getExpenseImportFilterCodes();
    return saoke
      .filter(r => {
        if (extraIdxSet.has(r.rowIndex)) return false;
        if (!isBatchHubCandidate(r)) return false;
        const cat = (r.postingCategoryCode ?? '').toUpperCase();
        if (cat && skipCodes.has(cat)) return false;
        const debit = r.debitAmount ?? 0;
        const credit = r.creditAmount ?? 0;
        if (showAllGiaoDich) return debit > 0 || credit > 0 || (r.amount ?? 0) !== 0;
        // Main đã map có thể là Thu-only — vẫn hiện để xem nhóm đã gán
        if (extraGdByMain[r.rowIndex]?.length) return true;
        if (Object.values(manualMap).includes(r.rowIndex)) return true;
        return debit > 0;
      })
      .sort((a, b) => {
        const da = normDateKey(a.transactionDate);
        const db = normDateKey(b.transactionDate);
        return da.localeCompare(db) || gdAmount(b) - gdAmount(a);
      });
  }, [saoke, showAllGiaoDich, extraGdByMain, manualMap]);

  const listDateOptions = useMemo(() => {
    const set = new Set<string>();
    for (const r of gdRows) {
      const k = normDateKey(r.transactionDate);
      if (k) set.add(k);
    }
    return [...set].sort();
  }, [gdRows]);

  const filteredGdRows = useMemo(() => {
    let rows = gdRows;
    if (listDateFilter) {
      rows = rows.filter(r => normDateKey(r.transactionDate) === listDateFilter);
    }
    if (filterMode === 'mapped') {
      rows = rows.filter(r => rowGroupMatch(r.rowIndex).matched);
    } else if (filterMode === 'mismatched') {
      rows = rows.filter(r => {
        const g = rowGroupMatch(r.rowIndex);
        return g.linked.length > 0 && !g.matched;
      });
    } else if (filterMode === 'unmapped') {
      rows = rows.filter(r => batchesForRow(r.rowIndex).length === 0);
    }
    return rows;
  }, [gdRows, listDateFilter, filterMode, batchesForRow, rowGroupMatch]);

  const mappedCount = useMemo(
    () => gdRows.filter(r => rowGroupMatch(r.rowIndex).matched).length,
    [gdRows, rowGroupMatch],
  );
  const mismatchedCount = useMemo(
    () => gdRows.filter(r => {
      const g = rowGroupMatch(r.rowIndex);
      return g.linked.length > 0 && !g.matched;
    }).length,
    [gdRows, rowGroupMatch],
  );
  const unmappedCount = useMemo(
    () => gdRows.filter(r => batchesForRow(r.rowIndex).length === 0).length,
    [gdRows, batchesForRow],
  );

  const assignGdIdx = assignGd?.rowIndex ?? null;

  const batchDateOptions = useMemo(() => {
    const set = new Set<string>();
    for (const g of bgroups) {
      const k = normDateKey(g.sheetDate);
      if (k) set.add(k);
    }
    // Luôn có option = ngày GD đang mở (kể cả chưa có lô ngày đó)
    if (batchDateFilter) set.add(batchDateFilter);
    return [...set].sort();
  }, [bgroups, batchDateFilter]);

  const pickerBatches = useMemo(() => {
    const q = batchSearch.trim().toLowerCase();
    let list = bgroups;
    if (batchDateFilter) {
      list = list.filter(g => normDateKey(g.sheetDate) === batchDateFilter);
    }
    if (q) {
      list = list.filter(g =>
        g.batchRef.toLowerCase().includes(q)
        || g.fileName.toLowerCase().includes(q)
        || g.lines.some(l => (l.description ?? '').toLowerCase().includes(q)
          || (l.beneficiaryName ?? '').toLowerCase().includes(q)
          || (l.staffNote ?? '').toLowerCase().includes(q)),
      );
    }
    return [...list].sort((a, b) =>
      (a.sheetDate ?? '').localeCompare(b.sheetDate ?? '') || a.batchRef.localeCompare(b.batchRef),
    );
  }, [bgroups, batchDateFilter, batchSearch]);

  const selectedBatches = useMemo(
    () => selectedBatchRefs
      .map(ref => bgroupByRef.get(ref))
      .filter((g): g is BRecGroup => !!g),
    [selectedBatchRefs, bgroupByRef],
  );

  /** Picker chỉ hiện lô chưa chọn — đã chọn nằm section riêng. */
  const availablePickerBatches = useMemo(
    () => pickerBatches.filter(g => !selectedBatchRefs.includes(g.batchRef)),
    [pickerBatches, selectedBatchRefs],
  );

  const selectedExtraGds = useMemo(
    () => selectedExtraIdxs
      .map(idx => saoke.find(r => r.rowIndex === idx))
      .filter((r): r is BankStatementImportRow => !!r),
    [selectedExtraIdxs, saoke],
  );

  const selectedBatchSum = useMemo(
    () => selectedBatches.reduce((s, g) => s + batchMatchAmount(g), 0),
    [selectedBatches],
  );
  const selectedSaokeSum = useMemo(() => {
    const main = assignGd ? gdSignedAmountForBatchMatch(assignGd) : 0;
    return main + selectedExtraGds.reduce((s, r) => s + gdSignedAmountForBatchMatch(r), 0);
  }, [assignGd, selectedExtraGds]);
  const gdAmt = assignGd ? gdAmount(assignGd) : 0;
  const assignDiff = selectedSaokeSum - selectedBatchSum;
  const assignMatch = selectedBatchRefs.length > 0 && Math.abs(assignDiff) < 1;

  const assignFileKey = assignGd ? sourceFileKey(assignGd.importReference) : '';

  const txDateOptions = useMemo(() => {
    if (!assignFileKey) return [] as string[];
    const set = new Set<string>();
    for (const r of saoke) {
      if (sourceFileKey(r.importReference) !== assignFileKey) continue;
      const k = normDateKey(r.transactionDate);
      if (k) set.add(k);
    }
    if (txDateFilter) set.add(txDateFilter);
    return [...set].sort();
  }, [saoke, assignFileKey, txDateFilter]);

  /**
   * Tab Giao dịch — mặc định:
   * Chi cùng ngày không ĐT · Thu/Chi cùng mã ref (với GD chính / lô chọn).
   * «Hiện tất cả»: mọi GD cùng file.
   */
  const availablePickerTxs = useMemo(() => {
    if (!assignGd || !assignFileKey) return [] as BankStatementImportRow[];
    const selected = new Set(selectedExtraIdxs);
    const q = txSearch.trim().toLowerCase();
    const mainDateKey = normDateKey(assignGd.transactionDate);
    let list = saoke.filter(r => {
      if (r.rowIndex === assignGd.rowIndex) return false;
      if (selected.has(r.rowIndex)) return false;
      if (sourceFileKey(r.importReference) !== assignFileKey) return false;
      if (showAllGiaoDich) {
        const debit = r.debitAmount ?? 0;
        const credit = r.creditAmount ?? 0;
        return debit > 0 || credit > 0 || (r.amount ?? 0) !== 0;
      }
      return isDefaultPickerTxCandidate(r, assignGd, {
        sameDateKey: mainDateKey,
        rowDateKey: normDateKey(r.transactionDate),
        selectedBatchRefs,
      });
    });
    if (txDateFilter) {
      list = list.filter(r => normDateKey(r.transactionDate) === txDateFilter);
    }
    if (q) {
      list = list.filter(r => {
        const refs = [
          ...(r.detectedBatchRefs ?? []),
          ...extractBulkRefsFromDescription(r.description),
        ].join(' ');
        return (r.referenceCode ?? '').toLowerCase().includes(q)
          || (r.description ?? '').toLowerCase().includes(q)
          || refs.toLowerCase().includes(q)
          || (r.counterpartyName ?? '').toLowerCase().includes(q);
      });
    }
    return [...list].sort((a, b) =>
      normDateKey(a.transactionDate).localeCompare(normDateKey(b.transactionDate))
      || gdAmount(b) - gdAmount(a),
    );
  }, [
    assignGd, assignFileKey, saoke, selectedExtraIdxs, selectedBatchRefs,
    txDateFilter, txSearch, showAllGiaoDich,
  ]);

  /** Emit map lô ↔ mã GD (main + phụ) — chờ seed xong nếu có initialLinks (tránh wipe Thu đã lưu). */
  useEffect(() => {
    if (!onReconcileLinksChange) return;
    if (initialLinks && initialLinks.length > 0 && !linksSeeded) return;
    const out: ReconcileStatementBatchLink[] = [];
    const seen = new Set<string>();
    const push = (row: BankStatementImportRow, batchRef: string) => {
      const key = `${row.importReference ?? row.rowIndex}|${batchRef}`;
      if (seen.has(key)) return;
      seen.add(key);
      out.push({
        statementRowIndex: row.rowIndex,
        statementImportReference: row.importReference,
        statementReferenceCode: row.referenceCode,
        batchRef,
      });
    };

    const batchRefs = new Set<string>([
      ...Object.keys(manualMap),
      ...[...autoMap.keys()].filter(ref => manualMap[ref] === undefined && !suppressedAuto[ref]),
    ]);

    for (const batchRef of batchRefs) {
      const main = resolveMappedRow(batchRef);
      if (!main) continue;
      push(main, batchRef);
      for (const extraIdx of extraGdByMain[main.rowIndex] ?? []) {
        const extra = saoke.find(r => r.rowIndex === extraIdx);
        if (extra) push(extra, batchRef);
      }
    }
    onReconcileLinksChange(out);
  }, [
    manualMap, suppressedAuto, autoMap, extraGdByMain, saoke,
    resolveMappedRow, onReconcileLinksChange, initialLinks, linksSeeded,
  ]);

  const openAssignForGd = useCallback((row: BankStatementImportRow) => {
    setDetailLine(null);
    setBatchSearch('');
    setTxSearch('');
    setPickerTab('lo');
    const mainIdx = resolveGroupMainIdx(row.rowIndex);
    const mainRow = saoke.find(r => r.rowIndex === mainIdx) ?? row;
    setAssignGd(prev => {
      if (prev && prev.rowIndex === mainRow.rowIndex
        && prev.description === mainRow.description
        && prev.transactionDate === mainRow.transactionDate) {
        setSelectedBatchRefs([]);
        setSelectedExtraIdxs([]);
        setBatchDateFilter('');
        setTxDateFilter('');
        return null;
      }
      const gdDate = normDateKey(mainRow.transactionDate);
      setBatchDateFilter(gdDate);
      setTxDateFilter(gdDate);
      setSelectedBatchRefs(batchesForRow(mainIdx).map(g => g.batchRef));
      // Luôn load đủ GD phụ đã gán (Thu+Chi) — kể cả khi click từ dòng phụ
      setSelectedExtraIdxs(extraGdByMain[mainIdx] ?? []);
      return mainRow;
    });
  }, [batchesForRow, extraGdByMain, resolveGroupMainIdx, saoke]);

  const closeAssign = useCallback(() => {
    setAssignGd(null);
    setSelectedBatchRefs([]);
    setSelectedExtraIdxs([]);
    setDetailLine(null);
    setBatchSearch('');
    setTxSearch('');
    setBatchDateFilter('');
    setTxDateFilter('');
    setPickerTab('lo');
  }, []);

  const toggleBatch = useCallback((batchRef: string) => {
    setSelectedBatchRefs(prev =>
      prev.includes(batchRef) ? prev.filter(r => r !== batchRef) : [...prev, batchRef],
    );
  }, []);

  const toggleExtraGd = useCallback((rowIndex: number) => {
    setSelectedExtraIdxs(prev =>
      prev.includes(rowIndex) ? prev.filter(i => i !== rowIndex) : [...prev, rowIndex],
    );
  }, []);

  const confirmAssign = useCallback(() => {
    if (assignGdIdx == null) return;
    const prevLinked = new Set(batchesForRow(assignGdIdx).map(g => g.batchRef));
    const next = new Set(selectedBatchRefs);

    setManualMap(prev => {
      const n = { ...prev };
      const prevExtras = extraGdByMain[assignGdIdx] ?? [];
      const clearIdxs = new Set([assignGdIdx, ...prevExtras]);
      for (const [ref, idx] of Object.entries(n)) {
        if (clearIdxs.has(idx) && !next.has(ref)) delete n[ref];
      }
      for (const ref of prevLinked) {
        if (!next.has(ref)) delete n[ref];
      }
      for (const ref of next) n[ref] = assignGdIdx;
      return n;
    });
    setSuppressedAuto(prev => {
      const n = { ...prev };
      for (const ref of next) delete n[ref];
      for (const ref of prevLinked) {
        if (!next.has(ref)) n[ref] = true;
      }
      return n;
    });
    setExtraGdByMain(prev => {
      const n = { ...prev };
      if (selectedExtraIdxs.length === 0) delete n[assignGdIdx];
      else n[assignGdIdx] = [...selectedExtraIdxs];
      return n;
    });
    closeAssign();
  }, [assignGdIdx, selectedBatchRefs, selectedExtraIdxs, batchesForRow, extraGdByMain, closeAssign]);

  if (batches.length === 0 || saoke.length === 0) {
    return (
      <div className={styles.reconcileEmpty}>
        Cần có cả file <strong>sao kê</strong> và file <strong>thanh toán lô</strong> để đối soát
      </div>
    );
  }

  if (bgroups.length === 0) {
    return (
      <div className={styles.reconcileEmpty}>
        Không phát hiện lệnh CK lô nào (thiếu Ref No trong header file thanh toán lô?)
      </div>
    );
  }

  const detailBatch = detailLine ? bgroupByRef.get(detailLine.batchRef) : undefined;
  const detailLineRow = detailBatch && detailLine ? detailBatch.lines[detailLine.idx] : undefined;

  return (
    <div className={styles.reconcilePanel}>
      <div className={styles.reconcileStats}>
        <button
          className={`${styles.reconcileStat} ${filterMode === 'all' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode('all')}
        >
          <span className={styles.reconcileStatVal}>{gdRows.length}</span>
          {' '}GD thiếu đối tượng
        </button>
        <button
          className={`${styles.reconcileStat} ${styles.reconcileStatOk} ${filterMode === 'mapped' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'mapped' ? 'all' : 'mapped'))}
        >
          <span className={styles.reconcileStatVal}>{mappedCount}</span> khớp
        </button>
        <button
          className={`${styles.reconcileStat} ${mismatchedCount > 0 ? styles.reconcileStatErr : styles.reconcileStatOk} ${filterMode === 'mismatched' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'mismatched' ? 'all' : 'mismatched'))}
        >
          <span className={styles.reconcileStatVal}>{mismatchedCount}</span> lệch tiền
        </button>
        <button
          className={`${styles.reconcileStat} ${unmappedCount > 0 ? styles.reconcileStatWarn : styles.reconcileStatOk} ${filterMode === 'unmapped' ? styles.reconcileStatActive : ''}`}
          onClick={() => setFilterMode(prev => (prev === 'unmapped' ? 'all' : 'unmapped'))}
        >
          <span className={styles.reconcileStatVal}>{unmappedCount}</span> chưa gắn lô
        </button>

        <label className={styles.showAllTxCheck} title="Hiện hub Chi+Thu thiếu đối tượng. GD phụ (Thu đã gắn) hiện trong slide-out Giao dịch.">
          <input
            type="checkbox"
            checked={showAllGiaoDich}
            onChange={e => setShowAllGiaoDich(e.target.checked)}
          />
          Hiện tất cả giao dịch
        </label>

        <label className={styles.reconcileDateFilter}>
          <span>Ngày GD</span>
          <select
            value={listDateFilter}
            onChange={e => setListDateFilter(e.target.value)}
          >
            <option value="">Tất cả ngày</option>
            {listDateOptions.map(d => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </label>
      </div>

      <div className={styles.reconcileTableWrap}>
        <table className={styles.reconcileTable}>
          <thead>
            <tr>
              <th className={styles.reconcileTh}>#</th>
              <th className={styles.reconcileTh}>Ngày</th>
              <th className={styles.reconcileTh}>Nội dung / mã GD sao kê</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Tiền SK</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThC}`}># lô</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Tổng lô (Thành công)</th>
              <th className={`${styles.reconcileTh} ${styles.reconcileThR}`}>Chênh</th>
              <th className={styles.reconcileTh}></th>
              <th className={styles.reconcileTh}>Chứng từ gốc</th>
            </tr>
          </thead>
          <tbody>
            {filteredGdRows.length === 0 ? (
              <tr>
                <td colSpan={9} className={styles.reconcileEmpty}>
                  {showAllGiaoDich
                    ? 'Không có giao dịch thiếu đối tượng'
                    : 'Không có GD thiếu đối tượng cần đối soát — gắn GD Thu/Chi phụ ở tab Giao dịch khi gán lô'}
                </td>
              </tr>
            ) : filteredGdRows.map((row, idx) => {
              const group = rowGroupMatch(row.rowIndex);
              const linked = group.linked;
              const batchSum = group.batchSum;
              const rowAmt = gdAmount(row);
              const variance = group.variance;
              const isMismatch = linked.length > 0 && !group.matched;
              const isOpen = assignGd != null
                && assignGd.rowIndex === row.rowIndex
                && assignGd.description === row.description
                && assignGd.transactionDate === row.transactionDate;
              const refsInDesc = extractBulkRefsFromDescription(row.description);
              const rowCls = [
                styles.reconcileTr,
                linked.length === 0 ? styles.reconcileTrMissing
                  : isMismatch ? styles.reconcileTrMismatch : styles.reconcileTrOk,
                isOpen ? styles.reconcileTrExplain : '',
              ].join(' ');

              return (
                <tr
                  key={`gd-${row.rowIndex}-${row.referenceCode ?? ''}-${row.transactionDate ?? ''}`}
                  className={rowCls}
                  style={{ cursor: 'pointer' }}
                  onClick={() => openAssignForGd(row)}
                >
                  <td className={styles.reconcileTd}>{idx + 1}</td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileTdDate}`}>
                    {row.transactionDate ?? '—'}
                  </td>
                  <td className={styles.reconcileTd}>
                    <div className={styles.reconcileRowDesc}>
                      {group.isExtra && <span className={styles.assignKindBadge} style={{ marginRight: 6 }}>phụ</span>}
                      {row.referenceCode ? (
                        <span className={styles.reconcileBatchRef} style={{ marginRight: 6 }}>{row.referenceCode}</span>
                      ) : null}
                      {row.description ?? '—'}
                    </div>
                    <div className={styles.reconcileRowMeta}>
                      {refsInDesc.length > 0 && (
                        <span className={styles.reconcileMultiHint}>
                          Ref: {refsInDesc.slice(0, 3).join(', ')}
                          {refsInDesc.length > 3 ? '…' : ''}
                        </span>
                      )}
                      {linked.length > 0 && (
                        <span>
                          {' · '}
                          {linked.map(g => g.batchRef).slice(0, 2).join(', ')}
                          {linked.length > 2 ? ` +${linked.length - 2}` : ''}
                          {group.memberCount > 1 ? ` · nhóm ${group.memberCount} GD` : ''}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThR}`} style={{ fontWeight: 700 }}>
                    <span style={{ color: gdMoneyColor(row) }}>
                      {formatAmount(rowAmt)}
                      {(row.debitAmount ?? 0) > 0 ? ' Chi' : (row.creditAmount ?? 0) > 0 ? ' Thu' : ''}
                    </span>
                    {isHoanTienStatementRow(row) && (
                      <div className={styles.descSub} style={{ color: '#a16207', fontWeight: 700 }}>Hoàn tiền</div>
                    )}
                    {group.memberCount > 1 && (
                      <div className={styles.descSub}>Σ {formatAmount(group.saokeSum)}</div>
                    )}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThC}`}>{linked.length || '—'}</td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileTdAmtBatch}`}>
                    {linked.length ? formatAmount(batchSum) : '—'}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileThR}`}>
                    {linked.length === 0 ? '—' : (
                      <span style={{ fontWeight: 700, color: group.matched ? '#15803d' : '#dc2626' }}>
                        {group.matched ? '✓ Khớp' : `${variance > 0 ? '+' : ''}${formatAmount(variance)}`}
                      </span>
                    )}
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.reconcileActions}`} onClick={e => e.stopPropagation()}>
                    <button className={styles.reconcileLookupBtn} onClick={() => openAssignForGd(row)}>
                      {isOpen ? '✕ Đóng' : linked.length ? 'Đổi lô' : '+ Gán lô'}
                    </button>
                  </td>
                  <td className={`${styles.reconcileTd} ${styles.categoryTdPath}`} title={row.importReference || undefined}>
                    <div className={styles.pathCell}>{row.importReference || '—'}</div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Slide-out: gán nhiều lô cho 1 GD */}
      {assignGd && (
        <PortalOverlay onClose={closeAssign}>
          <aside
            className={`${styles.explainSlideout} ${styles.assignSlideout}`}
            onClick={e => e.stopPropagation()}
            role="dialog"
            aria-label="Gán lô cho giao dịch sao kê"
          >
            <div className={styles.explainCardHeader}>
              <div className={styles.explainCardTitle}>
                <span className={styles.explainCardBadge}>Gán lô → GD</span>
                <span className={styles.explainCardDate}>{assignGd.transactionDate ?? '—'}</span>
                <span className={styles.explainCardAmt}>{formatAmount(gdAmt)}</span>
              </div>
              <button type="button" className={styles.explainCardClose} onClick={closeAssign}>✕</button>
            </div>

            <div className={styles.assignSumBar} data-match={selectedBatchRefs.length ? (assignMatch ? '1' : '0') : ''}>
              <div className={styles.assignSumItem}>
                <span>Tiền sao kê ({1 + selectedExtraIdxs.length} GD)</span>
                <b>{formatAmount(selectedSaokeSum)}</b>
              </div>
              <div className={styles.assignSumItem}>
                <span>Tổng {selectedBatchRefs.length} lô chọn</span>
                <b>{selectedBatchRefs.length ? formatAmount(selectedBatchSum) : '—'}</b>
              </div>
              <div className={styles.assignSumItem}>
                <span>Khớp?</span>
                <b style={{ color: !selectedBatchRefs.length ? '#9ca3af' : assignMatch ? '#15803d' : '#dc2626' }}>
                  {!selectedBatchRefs.length
                    ? '—'
                    : assignMatch
                      ? '✓ Khớp'
                      : `Lệch ${assignDiff > 0 ? '+' : ''}${formatAmount(assignDiff)}`}
                </b>
              </div>
              {selectedBatchRefs.length > 0 && !assignMatch && (
                <div className={styles.assignWarn}>
                  ⚠ Tổng lô (Thành công) chưa khớp tiền sao kê — dòng Thất bại không tính vào khớp; vẫn lưu được.
                </div>
              )}
            </div>

            <div className={styles.explainSlideBody}>
              {/* 1 — Sao kê chính (compact line) */}
              <div className={styles.assignMainGdSection}>
                <div className={styles.batchMdTitle}>
                  1. Sao kê chính
                  <span className={styles.batchMdTitleMeta}>không bỏ được</span>
                </div>
                <div className={styles.assignSelectedList}>
                  <div className={`${styles.assignSelectedItem} ${styles.assignMainGdItem}`}>
                    <div className={styles.assignSelectedMain}>
                      <span className={styles.reconcileBatchRef}>{gdRefLabel(assignGd)}</span>
                      <span className={styles.assignSelectedDate}>{assignGd.transactionDate ?? '—'}</span>
                      <span className={styles.assignSelectedAmt} style={{ color: gdMoneyColor(assignGd) }}>
                        {formatAmount(gdAmt)}
                        {(assignGd.debitAmount ?? 0) > 0 ? ' Chi' : (assignGd.creditAmount ?? 0) > 0 ? ' Thu' : ''}
                      </span>
                      <span className={styles.assignSelectedMeta} title={assignGd.description || undefined}>
                        {(assignGd.description || '—').slice(0, 80)}
                        {(assignGd.description?.length ?? 0) > 80 ? '…' : ''}
                      </span>
                      <span className={styles.pathCell} title={assignGd.importReference || undefined}>
                        {assignGd.importReference || '—'}
                      </span>
                    </div>
                  </div>
                </div>
              </div>

              {/* 2 — Đã chọn: lô + sao kê phụ */}
              <div className={styles.assignSelectedSection}>
                <div className={styles.batchMdTitle}>
                  2. Sao kê / lô đã chọn
                  <span className={styles.batchMdTitleMeta}>
                    {selectedExtraGds.length} GD · {selectedBatches.length} lô · {formatAmount(selectedBatchSum)}
                  </span>
                </div>
                {selectedExtraGds.length === 0 && selectedBatches.length === 0 ? (
                  <div className={styles.assignSelectedEmpty}>
                    Chưa chọn — chọn ở mục «3. Chọn lô / giao dịch» bên dưới
                  </div>
                ) : (
                  <div className={styles.assignSelectedList}>
                    {selectedExtraGds.map(r => (
                      <div key={`tx-${r.rowIndex}`} className={`${styles.assignSelectedItem} ${styles.assignSelectedTxItem}`}>
                        <div className={styles.assignSelectedMain}>
                          <span className={styles.assignKindBadge}>GD</span>
                          <span className={styles.reconcileBatchRef}>{gdRefLabel(r)}</span>
                          <span className={styles.assignSelectedDate}>{r.transactionDate ?? '—'}</span>
                          <span className={styles.assignSelectedAmt} style={{ color: gdMoneyColor(r) }}>
                            {formatAmount(gdAmount(r))}
                            {(r.debitAmount ?? 0) > 0 ? ' Chi' : (r.creditAmount ?? 0) > 0 ? ' Thu' : ''}
                            {isHoanTienStatementRow(r) ? ' · Hoàn' : ''}
                          </span>
                          <span className={styles.assignSelectedMeta} title={r.description || undefined}>
                            {(r.description || '—').slice(0, 60)}
                            {(r.description?.length ?? 0) > 60 ? '…' : ''}
                          </span>
                        </div>
                        <div className={styles.assignSelectedActions}>
                          <button
                            type="button"
                            className={styles.assignRemoveBtn}
                            onClick={() => toggleExtraGd(r.rowIndex)}
                            title="Bỏ chọn GD"
                          >
                            Bỏ
                          </button>
                        </div>
                      </div>
                    ))}
                    {selectedBatches.map(g => {
                      const notes = [...new Set(g.lines.map(l => l.staffNote || l.companyCode).filter(Boolean))];
                      const fts = [...new Set(g.lines.map(l => l.ftNumber).filter(Boolean))];
                      const path = batchGroupPath(g);
                      return (
                        <div key={g.batchRef} className={styles.assignSelectedItem}>
                          <div className={styles.assignSelectedMain}>
                            <span className={`${styles.assignKindBadge} ${styles.assignKindBadgeLo}`}>Lô</span>
                            <span className={styles.reconcileBatchRef}>{g.batchRef}</span>
                            <span className={styles.assignSelectedDate}>{g.sheetDate ?? '—'}</span>
                            <span className={styles.assignSelectedAmt}>{formatAmount(g.successAmount)}</span>
                            <span className={styles.assignSelectedMeta}>
                              {g.successCount} Thành công
                              {g.failedCount > 0 ? ` · ${g.failedCount} Thất bại · ${formatAmount(g.failedAmount)}` : ''}
                              {fts.length > 0 ? ` · ${fts.length} FT` : ''}
                              {notes.length > 0 ? ` · ${notes.slice(0, 2).join(', ')}` : ''}
                            </span>
                            <span className={styles.pathCell} title={path}>{path}</span>
                          </div>
                          <div className={styles.assignSelectedActions}>
                            <button
                              type="button"
                              className={styles.reconcileLookupBtn}
                              onClick={() => setDetailLine({ batchRef: g.batchRef, idx: 0 })}
                            >
                              Chi tiết
                            </button>
                            <button
                              type="button"
                              className={styles.assignRemoveBtn}
                              onClick={() => toggleBatch(g.batchRef)}
                              title="Bỏ chọn lô"
                            >
                              Bỏ
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* 3 — Chọn lô / giao dịch */}
              <div className={styles.assignPickerSection}>
                <div className={styles.batchMdTitle}>
                  3. Chọn lô / giao dịch để gắn
                  <span className={styles.batchMdTitleMeta}>tick để thêm vào mục 2</span>
                </div>
                <div className={styles.assignPickerTabs}>
                  <button
                    type="button"
                    className={`${styles.assignPickerTab} ${pickerTab === 'lo' ? styles.assignPickerTabActive : ''}`}
                    onClick={() => setPickerTab('lo')}
                  >
                    Lô
                    <span className={styles.contentTabCount}>{availablePickerBatches.length}</span>
                  </button>
                  <button
                    type="button"
                    className={`${styles.assignPickerTab} ${pickerTab === 'gd' ? styles.assignPickerTabActive : ''}`}
                    onClick={() => setPickerTab('gd')}
                  >
                    Giao dịch
                    <span className={styles.contentTabCount}>{availablePickerTxs.length}</span>
                  </button>
                </div>

                {pickerTab === 'lo' ? (
                  <div className={styles.assignPickerInner}>
                    <div className={styles.reconcileDateFilterRow}>
                      <label className={styles.reconcileDateFilter}>
                        <span>Ngày lô</span>
                        <select
                          value={batchDateFilter}
                          onChange={e => setBatchDateFilter(e.target.value)}
                        >
                          <option value="">Tất cả ngày</option>
                          {batchDateOptions.map(d => (
                            <option key={d} value={d}>{d}</option>
                          ))}
                        </select>
                      </label>
                      {batchDateFilter && availablePickerBatches.length === 0 && pickerBatches.length === 0 && (
                        <span className={styles.reconcileMultiHint}>
                          Không có lô ngày {batchDateFilter} — chọn «Tất cả ngày» hoặc ngày khác
                        </span>
                      )}
                      <input
                        className={styles.reconcileLookupInput}
                        style={{ flex: 1, marginBottom: 0 }}
                        placeholder="Tìm mã lô, nội dung, ghi chú NV…"
                        value={batchSearch}
                        onChange={e => setBatchSearch(e.target.value)}
                      />
                    </div>

                    <div className={styles.assignTableWrap}>
                      <table className={`${styles.categoryTable} ${styles.assignNoSticky}`}>
                        <thead>
                          <tr>
                            <th className={styles.categoryTh} style={{ width: 36 }} />
                            <th className={styles.categoryTh} style={{ minWidth: 140 }}>Mã lô (Ref)</th>
                            <th className={styles.categoryTh} style={{ width: 88 }}>Ngày</th>
                            <th className={styles.categoryTh} style={{ width: 120, textAlign: 'right' }}>Thành công (khớp)</th>
                            <th className={styles.categoryTh} style={{ width: 110, textAlign: 'right' }}>Thất bại</th>
                            <th className={styles.categoryTh} style={{ width: 56, textAlign: 'center' }}>#</th>
                            <th className={styles.categoryTh}>File / ghi chú NV</th>
                            <th className={styles.categoryTh} style={{ minWidth: 140 }}>Chứng từ gốc</th>
                          </tr>
                        </thead>
                        <tbody>
                          {availablePickerBatches.length === 0 ? (
                            <tr>
                              <td colSpan={8} className={styles.reconcileEmpty}>
                                {pickerBatches.length > 0 && selectedBatches.length > 0
                                  ? 'Đã chọn hết lô trong filter hiện tại'
                                  : 'Không có lô (đổi filter ngày / tìm kiếm)'}
                              </td>
                            </tr>
                          ) : availablePickerBatches.map(g => {
                            const notes = [...new Set(g.lines.map(l => l.staffNote || l.companyCode).filter(Boolean))];
                            const path = batchGroupPath(g);
                            return (
                              <tr
                                key={g.batchRef}
                                className={styles.categoryTr}
                                onClick={() => toggleBatch(g.batchRef)}
                              >
                                <td className={styles.categoryTd} style={{ textAlign: 'center' }}>
                                  <input
                                    type="checkbox"
                                    checked={false}
                                    onChange={() => toggleBatch(g.batchRef)}
                                    onClick={e => e.stopPropagation()}
                                  />
                                </td>
                                <td className={styles.categoryTd}>
                                  <span className={styles.reconcileBatchRef}>{g.batchRef}</span>
                                </td>
                                <td className={styles.categoryTd} style={{ color: '#2563eb', fontWeight: 600, whiteSpace: 'nowrap' }}>
                                  {g.sheetDate ?? '—'}
                                </td>
                                <td className={styles.categoryTd} style={{ textAlign: 'right', fontWeight: 700, color: '#7c3aed' }}>
                                  {formatAmount(g.successAmount)}
                                </td>
                                <td className={styles.categoryTd} style={{ textAlign: 'right', fontWeight: 600, color: g.failedAmount > 0 ? '#b45309' : '#9ca3af' }}>
                                  {g.failedAmount > 0 ? formatAmount(g.failedAmount) : '—'}
                                </td>
                                <td className={styles.categoryTd} style={{ textAlign: 'center' }}>{g.lineCount}</td>
                                <td className={styles.categoryTd}>
                                  <div className={styles.descSub}>{g.fileName.replace(/\.[^.]+$/, '')}</div>
                                  {notes.length > 0 && (
                                    <div style={{ color: '#9a3412', fontWeight: 600, fontSize: 11 }}>
                                      {notes.slice(0, 4).join(', ')}{notes.length > 4 ? '…' : ''}
                                    </div>
                                  )}
                                  <button
                                    type="button"
                                    className={styles.reconcileLookupBtn}
                                    style={{ marginTop: 4 }}
                                    onClick={e => {
                                      e.stopPropagation();
                                      setDetailLine({ batchRef: g.batchRef, idx: 0 });
                                    }}
                                  >
                                    Xem chi tiết
                                  </button>
                                </td>
                                <td className={`${styles.categoryTd} ${styles.categoryTdPath}`} title={path}>
                                  <div className={styles.pathCell}>{path}</div>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                ) : (
                  <div className={styles.assignPickerInner}>
                    <div className={styles.reconcileDateFilterRow}>
                      <label className={styles.reconcileDateFilter}>
                        <span>Ngày</span>
                        <select
                          value={txDateFilter}
                          onChange={e => setTxDateFilter(e.target.value)}
                        >
                          <option value="">Tất cả ngày</option>
                          {txDateOptions.map(d => (
                            <option key={d} value={d}>{d}</option>
                          ))}
                        </select>
                      </label>
                      <input
                        className={styles.reconcileLookupInput}
                        style={{ flex: 1, marginBottom: 0 }}
                        placeholder="Tìm mã FT, nội dung, ref lô…"
                        value={txSearch}
                        onChange={e => setTxSearch(e.target.value)}
                      />
                      <label
                        className={styles.showAllTxCheck}
                        title="Hiện mọi GD cùng file. Mặc định chỉ: Chi cùng ngày không ĐT + Thu/Chi cùng mã ref."
                      >
                        <input
                          type="checkbox"
                          checked={showAllGiaoDich}
                          onChange={e => setShowAllGiaoDich(e.target.checked)}
                        />
                        Hiện tất cả giao dịch
                      </label>
                    </div>
                    {!assignFileKey && (
                      <div className={styles.reconcileMultiHint}>
                        Sao kê chính thiếu chứng từ gốc — không lọc được theo file
                      </div>
                    )}
                    <div className={styles.assignTableWrap}>
                      <table className={`${styles.categoryTable} ${styles.assignNoSticky}`}>
                        <thead>
                          <tr>
                            <th className={styles.categoryTh} style={{ width: 36 }} />
                            <th className={styles.categoryTh} style={{ minWidth: 140 }}>Mã GD (FT)</th>
                            <th className={styles.categoryTh} style={{ width: 110 }}>Ngày</th>
                            <th className={styles.categoryTh} style={{ width: 110, textAlign: 'right' }}>Số tiền</th>
                            <th className={styles.categoryTh}>Nội dung / ref lô</th>
                            <th className={styles.categoryTh} style={{ minWidth: 120 }}>Chứng từ gốc</th>
                          </tr>
                        </thead>
                        <tbody>
                          {availablePickerTxs.length === 0 ? (
                            <tr>
                              <td colSpan={6} className={styles.reconcileEmpty}>
                                {assignFileKey
                                  ? (showAllGiaoDich
                                    ? 'Không còn GD cùng file (đổi filter Ngày / Nội dung)'
                                    : 'Không còn GD phù hợp — mặc định: Chi cùng ngày không ĐT · cùng mã ref. Bật «Hiện tất cả» nếu cần.')
                                  : 'Không có GD để chọn'}
                              </td>
                            </tr>
                          ) : availablePickerTxs.map(r => {
                            const refs = [
                              ...(r.detectedBatchRefs ?? []),
                              ...extractBulkRefsFromDescription(r.description),
                            ];
                            const uniqRefs = [...new Set(refs.map(normalizeBulkRef).filter(Boolean))];
                            return (
                              <tr
                                key={`pick-tx-${r.rowIndex}`}
                                className={styles.categoryTr}
                                onClick={() => toggleExtraGd(r.rowIndex)}
                              >
                                <td className={styles.categoryTd} style={{ textAlign: 'center' }}>
                                  <input
                                    type="checkbox"
                                    checked={false}
                                    onChange={() => toggleExtraGd(r.rowIndex)}
                                    onClick={e => e.stopPropagation()}
                                  />
                                </td>
                                <td className={styles.categoryTd}>
                                  <span className={styles.reconcileBatchRef}>{gdRefLabel(r)}</span>
                                </td>
                                <td className={styles.categoryTd} style={{ color: '#2563eb', fontWeight: 600, whiteSpace: 'nowrap' }}>
                                  {r.transactionDate ?? '—'}
                                </td>
                                <td className={styles.categoryTd} style={{
                                  textAlign: 'right',
                                  fontWeight: 700,
                                  color: gdMoneyColor(r),
                                }}>
                                  {formatAmount(gdAmount(r))}
                                  {(r.debitAmount ?? 0) > 0 ? ' Chi' : (r.creditAmount ?? 0) > 0 ? ' Thu' : ''}
                                </td>
                                <td className={`${styles.categoryTd} ${styles.categoryTdDesc}`}>
                                  <div className={styles.descFull}>{r.description || '—'}</div>
                                  {isHoanTienStatementRow(r) && (
                                    <div className={styles.descSub} style={{ color: '#a16207', fontWeight: 700 }}>
                                      Hoàn tiền
                                    </div>
                                  )}
                                  {uniqRefs.length > 0 && (
                                    <div className={styles.descSub} style={{ color: '#7c3aed', fontWeight: 600 }}>
                                      Ref lô: {uniqRefs.slice(0, 3).join(', ')}
                                      {uniqRefs.length > 3 ? '…' : ''}
                                    </div>
                                  )}
                                  {r.counterpartyName?.trim() && (
                                    <div className={styles.descSub}>{r.counterpartyName.trim()}</div>
                                  )}
                                </td>
                                <td className={`${styles.categoryTd} ${styles.categoryTdPath}`} title={r.importReference || undefined}>
                                  <div className={styles.pathCell}>{r.importReference || '—'}</div>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className={styles.assignFooter}>
              <button type="button" className={styles.assignCancelBtn} onClick={closeAssign}>Hủy</button>
              <button type="button" className={styles.assignConfirmBtn} onClick={confirmAssign}>
                Lưu gắn ({selectedBatchRefs.length} lô
                {selectedExtraIdxs.length > 0 ? ` · ${selectedExtraIdxs.length} GD` : ''})
              </button>
            </div>
          </aside>

          {detailBatch && detailLineRow && (
            <aside
              className={`${styles.explainSlideout} ${styles.lineDetailSlideout}`}
              onClick={e => e.stopPropagation()}
              role="dialog"
              aria-label="Chi tiết lô"
              style={{ boxShadow: '-12px 0 28px rgba(15,23,42,0.25)' }}
            >
              <div className={`${styles.explainCardHeader} ${styles.batchDetailHeader}`}>
                <div className={styles.batchDetailHeaderMain}>
                  <div className={styles.explainCardTitle}>
                    <span className={styles.explainCardBadge}>Chi tiết lô</span>
                    <span className={styles.reconcileBatchRef}>{detailBatch.batchRef}</span>
                  </div>
                  <div className={styles.batchDetailSumRow}>
                    <div className={styles.batchDetailSumItem}>
                      <span className={styles.batchDetailSumLabel}>Tổng thành công</span>
                      <span className={styles.batchDetailSumOk}>
                        {formatAmount(detailBatch.successAmount)}
                        <span className={styles.batchDetailSumCount}>{detailBatch.successCount} dòng</span>
                      </span>
                    </div>
                    <div className={styles.batchDetailSumItem}>
                      <span className={styles.batchDetailSumLabel}>Tổng thất bại</span>
                      <span className={styles.batchDetailSumFail}>
                        {formatAmount(detailBatch.failedAmount)}
                        <span className={styles.batchDetailSumCount}>{detailBatch.failedCount} dòng</span>
                      </span>
                    </div>
                  </div>
                </div>
                <button type="button" className={styles.explainCardClose} onClick={() => setDetailLine(null)}>✕</button>
              </div>
              <div className={styles.explainSlideBody}>
                <div className={styles.assignDetailScroll} style={{ maxHeight: 'none', flex: 1 }}>
                  <table className={`${styles.categoryTable} ${styles.assignNoSticky}`}>
                    <thead>
                      <tr>
                        <th className={styles.categoryTh}>#</th>
                        <th className={styles.categoryTh}>Người nhận</th>
                        <th className={styles.categoryTh} style={{ textAlign: 'right' }}>Tiền</th>
                        <th className={styles.categoryTh}>TT</th>
                        <th className={styles.categoryTh}>Nội dung</th>
                        <th className={styles.categoryTh}>Ghi chú NV</th>
                        <th className={styles.categoryTh} style={{ minWidth: 140 }}>Chứng từ gốc</th>
                      </tr>
                    </thead>
                    <tbody>
                      {detailBatch.lines.map((l, i) => {
                        const ok = isBatchLineSuccess(l.status);
                        return (
                        <tr
                          key={`${detailBatch.batchRef}-${i}`}
                          className={styles.categoryTr}
                          style={ok ? undefined : { background: '#fef9c3' }}
                        >
                          <td className={styles.categoryTd}>{i + 1}</td>
                          <td className={styles.categoryTd}>
                            <div className={styles.descFull}>{l.beneficiaryName}</div>
                            <div className={styles.descSub}>{l.bankName}</div>
                          </td>
                          <td className={styles.categoryTd} style={{ textAlign: 'right', color: '#7c3aed', fontWeight: 700 }}>
                            {formatAmount(l.amount)}
                          </td>
                          <td className={styles.categoryTd} style={{ color: ok ? '#15803d' : '#b45309', fontWeight: 600, whiteSpace: 'nowrap' }}>
                            {l.status || 'Thành công'}
                          </td>
                          <td className={`${styles.categoryTd} ${styles.categoryTdDesc}`}>
                            <div className={styles.descFull}>{l.description || '—'}</div>
                          </td>
                          <td className={styles.categoryTd} style={{ color: '#9a3412', fontWeight: 600 }}>
                            {l.staffNote || l.companyCode || '—'}
                          </td>
                          <td className={`${styles.categoryTd} ${styles.categoryTdPath}`} title={l.sourcePath || undefined}>
                            <div className={styles.pathCell}>{l.sourcePath || '—'}</div>
                          </td>
                        </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            </aside>
          )}
        </PortalOverlay>
      )}
    </div>
  );
};

export default BatchReconcilePanel;
