export type PostingCategoryKind =
  | 'payment'   // Thanh toán công nợ NCC (Dr 331 / Cr 112)
  | 'expense'   // Chi phí P&L (lương, thuê, điện nước…)
  | 'transfer'  // Chuyển nội bộ / rút tiền
  | 'income'    // Thu tiền (báo có)
  | 'fee'       // Phí NH / POS
  | 'unknown';  // Chưa phân loại

export interface PostingCategoryEntry {
  code: string;
  label: string;
  kind: PostingCategoryKind;
  /** Mã định khoản gợi ý (từ REVA: BTK2014, BN001, UNC-BHXH…) */
  postingCodes: string[];
  /** Keyword match trên cả description + counterparty */
  keywords?: RegExp[];
  /** Keyword match chỉ trên description (không check counterparty) */
  descriptionOnlyKeywords?: RegExp[];
  /** Keyword match trên tên đối tác / NCC */
  supplierKeywords?: RegExp[];
  /** Ưu tiên — số cao hơn được kiểm tra trước */
  priority?: number;
}

/** Strip diacritics + lowercase để so khớp keyword không phân biệt dấu. */
export function normPostingText(s: string): string {
  return String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase();
}

