/** Chip filter từ BE (ExpenseItem.ShowOnImportFilter) — không cần gán lô. */
export interface ExpenseImportFilterDto {
  code: string;
  name: string;
  grepKeys?: string | null;
  accountCode?: string;
}

/** Convert GrepKeys (`a|b`) → RegExp[] cho detect FE. */
export function grepKeysToKeywords(raw?: string | null): RegExp[] {
  if (!raw?.trim()) return [];
  return raw
    .split(/[|\n\r;]/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(k => {
      const escaped = k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      return new RegExp(escaped, 'i');
    });
}

export function expenseFiltersToCategories(
  filters: ExpenseImportFilterDto[],
): PostingCategoryEntry[] {
  return filters
    .filter(f => f.code?.trim())
    .map(f => ({
      code: f.code.trim().toUpperCase(),
      label: f.name?.trim() || f.code,
      kind: 'expense' as const,
      postingCodes: [],
      priority: 95,
      keywords: grepKeysToKeywords(f.grepKeys),
    }));
}

/** Danh sách đã sắp xếp theo priority giảm dần (bỏ fallback). */
let extraImportFilterCategories: PostingCategoryEntry[] = [];

/** Gọi khi vào import view — load chip từ `GET .../expense-filters`. */
export function setExpenseImportFilterCategories(filters: ExpenseImportFilterDto[]): void {
  extraImportFilterCategories = expenseFiltersToCategories(filters);
}

export function getExpenseImportFilterCategories(): PostingCategoryEntry[] {
  return extraImportFilterCategories;
}

export function getExpenseImportFilterCodes(): Set<string> {
  return new Set(extraImportFilterCategories.map(c => c.code));
}

const SORTED_STATIC = [...POSTING_CATEGORIES]
  .filter(c => c.code !== 'CHUA_PHAN_LOAI')
  .sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0));

const FALLBACK_CATEGORY = POSTING_CATEGORIES.find(c => c.code === 'CHUA_PHAN_LOAI')!;

function matchCategory(
  cat: PostingCategoryEntry,
  normDesc: string,
  normCp: string,
): boolean {
  const allKw = [...(cat.keywords ?? []), ...(cat.descriptionOnlyKeywords ?? [])];
  if (allKw.some(re => re.test(normDesc))) return true;
  if (cat.supplierKeywords && normCp) {
    if (cat.supplierKeywords.some(re => re.test(normCp))) return true;
  }
  return false;
}

/**
 * Phát hiện loại định khoản từ nội dung chuyển khoản + tên đối tác.
 * Ưu tiên chip BE (ShowOnImportFilter), rồi POSTING_CATEGORIES tĩnh.
 * Trả CHUA_PHAN_LOAI nếu không khớp.
 */
export function detectPostingCategory(
  description: string,
  counterparty?: string,
): PostingCategoryEntry {
  const normDesc = normPostingText(description ?? '');
  const normCp = normPostingText(counterparty ?? '');

  const extra = [...extraImportFilterCategories].sort(
    (a, b) => (b.priority ?? 0) - (a.priority ?? 0),
  );
  for (const cat of extra) {
    if (matchCategory(cat, normDesc, normCp)) return cat;
  }

  for (const cat of SORTED_STATIC) {
    if (matchCategory(cat, normDesc, normCp)) return cat;
  }

  return FALLBACK_CATEGORY;
}

/** Gắn lại category cho rows sau khi load filter BE. */
export function applyExpenseImportFiltersToRows<T extends {
  description?: string;
  counterpartyName?: string;
  postingCategoryCode?: string;
  postingCategoryLabel?: string;
}>(rows: T[]): T[] {
  if (extraImportFilterCategories.length === 0) return rows;
  return rows.map(r => {
    const cat = detectPostingCategory(r.description ?? '', r.counterpartyName ?? '');
    return {
      ...r,
      postingCategoryCode: cat.code,
      postingCategoryLabel: cat.label,
    };
  });
}

